-- ============================================-- 清理重复数据-- ============================================-- 1. 清理 agents 表重复数据-- 保留最新的一条，删除其他重复记录WITH duplicates AS (    SELECT id,        ROW_NUMBER() OVER (        PARTITION BY user_id, agent_id         ORDER BY updated_at DESC, created_at DESC        ) as rn    FROM agents    WHERE deleted_at IS NULL)DELETE FROM agents WHERE id IN (    SELECT id FROM duplicates WHERE rn > 1);-- 2. 检查并修复 settings 表-- 如果 user_id 为 null，更新为匿名用户UPDATE settings SET user_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890'::UUID WHERE user_id IS NULL;-- 3. 验证清理结果SELECT 'agents' as table_name, COUNT(*) as total, COUNT(DISTINCT agent_id) as unique_countFROM agents WHERE deleted_at IS NULLUNION ALLSELECT 'settings', COUNT(*), COUNT(DISTINCT user_id)FROM settings WHERE deleted_at IS NULL;